## 🗄️ قاعدة البيانات (Prisma + SQLite)

### .env
```dotenv
DATABASE_URL="file:./dev.db"
```

### prisma/schema.prisma
```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

/*-------------------- الجمعية --------------------*/
model Association {
  id          Int      @id @default(autoincrement())
  name        String
  address     String?
  phone       String?
  currency    String   @default("د.إ") // أو أي عملة تريدها
  createdAt   DateTime @default(now())
}

/*-------------------- الأعضاء --------------------*/
model Member {
  id          Int       @id @default(autoincrement())
  fullName    String
  email       String    @unique
  phone       String?
  balance     Decimal   @default(0.0)
  createdAt   DateTime  @default(now())
  transactions Transaction[]
}

/*-------------------- المعاملات --------------------*/
model Transaction {
  id            Int       @id @default(autoincrement())
  type          TransactionType
  amount        Decimal
  description   String?
  fromMemberId  Int?      // للـتحويل
  toMemberId    Int?      // للـتحويل
  memberId      Int?      // إيداع/سحب
  createdAt     DateTime  @default(now())

  // العلاقات
  member        Member?   @relation("MemberTransactions", fields: [memberId], references: [id])
  fromMember    Member?   @relation("FromTransfers", fields: [fromMemberId], references: [id])
  toMember      Member?   @relation("ToTransfers", fields: [toMemberId], references: [id])
}

/* نوع المعاملة */
enum TransactionType {
  DEPOSIT   // إيداع
  WITHDRAW  // سحب
  TRANSFER  // تحويل
}

/*-------------------- صندوق الجمعية --------------------*/
model Cashbox {
  id          Int       @id @default(autoincrement())
  balance     Decimal   @default(0.0)
  movements   CashMovement[]
}

/* حركات الصندوق اليومية */
model CashMovement {
  id          Int       @id @default(autoincrement())
  type        CashMovementType
  amount      Decimal
  description String?
  createdAt   DateTime @default(now())
  cashboxId   Int
  cashbox     Cashbox  @relation(fields: [cashboxId], references: [id])
}

enum CashMovementType {
  IN   // إيداع في الصندوق
  OUT  // سحب من الصندوق
}
```

> بعد حفظ الملف، شغّل:
> ```bash
> npx prisma migrate dev --name init
> npx prisma generate
> ```

